var model = new GraphRenderModel(settings);

// Get node bounds in canvas coordinates
var bounds = model.GetNodeBounds(node);

// Get port position
var portPos = model.GetPortPosition(node, port, isOutput: true);

// Calculate edge endpoints
var (start, end) = model.GetEdgeEndpoints(edge, graph);

public class MyCustomRenderer : INodeRenderer, IDirectNodeRenderer
{
    // INodeRenderer implementation for visual tree mode
    public Control CreateNodeVisual(Node node, NodeRenderContext context) { ... }

    // IDirectNodeRenderer implementation for direct mode
    public void DrawNode(DrawingContext context, Node node, DirectNodeRenderContext ctx)
    {
        // Draw custom shape
        var geometry = new EllipseGeometry(ctx.ScreenBounds);
        context.DrawGeometry(ctx.Background, ctx.BorderPen, geometry);

        // Draw label
        if (!ctx.IsEditing)
        {
            // Draw text...
        }
    }
}

member.summary:
Gets the geometry for a vector icon. This takes precedence over .
Use this to integrate with any icon library (Lucide, Material, FontAwesome, etc.)
by providing the icon's path data.


// Simple arrow icon
protected override Geometry? IconGeometry => 
    Geometry.Parse("M5 12h14M12 5l7 7-7 7");

// Or use a static geometry for better performance
private static readonly Geometry _icon = Geometry.Parse("M5 12h14");
protected override Geometry? IconGeometry => _icon;
